void EntranceIdentity(){
    struct Sink final:RecordIngressSink {void OnAttributedBytes(const RecordAttribution&,std::int32_t,const void*,std::size_t)override{}} sink;
    auto& table=ServiceRecordTable::Process();auto reserved=table.ReserveRecord("host.public.shim");Check(bool(reserved),"reserve original table");
    auto client=table.Expose(*reserved.value,RecordRole::Client,sink);auto server=table.Expose(*reserved.value,RecordRole::Server,sink);Check(bool(client)&&bool(server),"original role entrances");
    auto a=std::make_shared<PublicSocketBackend>(ShimConfig());auto b=std::make_shared<PublicSocketBackend>(ShimConfig());
    Check(a->ConfigureEntrance({})==BackendStatus::InvalidIdentity&&a->ConfigureEntrance(*server.value)==BackendStatus::InvalidIdentity,"empty/wrong role rejected");
    Check(a->ConfigureEntrance(*client.value)==BackendStatus::None&&a->ConfigureEntrance(*client.value)==BackendStatus::None,"same original association idempotent");
    const auto fixed=a->Observe().entry_index;Check(b->ConfigureEntrance(*client.value)==BackendStatus::DuplicateRecord&&!b->Observe().configured&&a->Observe().entry_index==fixed,"collision cannot replace fixed state");
    Check(fake_sdk::sockets==0,"configuration never invokes public API");
    Check(table.AbandonExposure(*client.value)==RecordStatus::None&&table.AbandonExposure(*server.value)==RecordStatus::None,"release unused pending anchors");
    Check(table.ReleaseSink(*client.value,sink)==RecordStatus::None,"release stack sink");
}
